DROP TABLE t0; DROP TABLE t1; CREATE TABLE t0(c0 INT,c1 INT UNIQUE); CREATE TABLE t1(c0 INT); INSERT INTO t0(c0,c1) VALUES(0,1); INSERT INTO t1(c0) VALUES(1); CREATE TABLE r1 AS SELECT ALL * FROM t1 NATURAL JOIN t0 WHERE t1.c0=t0.c1; CREATE TABLE r2 AS SELECT ALL * FROM t1 NATURAL JOIN t0 WHERE likely(t1.c0=t0.c1); CREATE TABLE r3 AS SELECT ALL * FROM t1,t0 WHERE likely(t1.c0=t0.c1) AND t1.c0=t0.c0;